package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.LastErrorVO;

class LastErrorValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of last error of observed probe")
  void test_last_error_value_holder_assign_plain_value() {
    Object holder = new Object();
    LastErrorValueHolder<Object> value = new LastErrorValueHolder<>(holder);
    Assertions.assertSame(holder, value.lastError("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLastErrorValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getLastError().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.lastErrorNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLastErrorValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLastError().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of last error of observed probe")
  void test_last_error_value_holder_assign_value_object() {
    Object holder = new Object();
    LastErrorValueHolder<Object> value = new LastErrorValueHolder<>(holder);
    LastErrorVO vo = LastErrorVO.from("one");
    Assertions.assertFalse(value.getLastErrorValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.lastError(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLastErrorValue().orElseThrow());
    Assertions.assertSame(holder, value.lastError(Optional.empty()));
    Assertions.assertFalse(value.getLastErrorValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.lastError(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLastErrorValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of last error of observed probe against the original")
  void test_last_error_value_holder_read() {
    Object holder = new Object();
    LastErrorValueHolder<Object> value = new LastErrorValueHolder<>(holder);
    LastErrorVO vo = LastErrorVO.from("one");
    LastErrorVO other = LastErrorVO.from("one");
    ObservedProbe original = Mockito.mock(ObservedProbe.class);
    Mockito.when(original.getLastErrorValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLastError(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLastError(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.lastError(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLastError(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLastError(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of last error of observed probe")
  void test_last_error_value_holder_unset() {
    Object holder = new Object();
    LastErrorValueHolder<Object> value = new LastErrorValueHolder<>(holder);
    LastErrorVO vo = LastErrorVO.from("one");
    value.lastError(vo);
    Assertions.assertSame(holder, value.unsetLastErrorIfMatches("lastError_other"));
    Assertions.assertTrue(value.getLastErrorValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLastErrorIfMatches("lastError"));
    Assertions.assertFalse(value.getLastErrorValue().isPresent(),
        "The field name must clear the value");
    value.lastError(vo);
    Assertions.assertSame(holder, value.unsetLastError());
    Assertions.assertFalse(value.getLastErrorValue().isPresent(), "Unset must clear the value");
  }
}
